  onPageScroll: function onPageScroll(e) {
    that.scrollTop = e.scrollTop;
  },
  // 监听 - 页面每次【加载时】执行(如：前进)
  onLoad: function onLoad() {var options = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : {};
    that = this;
    vk = that.vk;
    that.options = options;
    that.init(options);
  },
  // 监听 - 页面【首次渲染完成时】执行。注意如果渲染速度快，会在页面进入动画完成前触发
  onReady: function onReady() {},
  // 监听 - 页面每次【显示时】执行(如：前进和返回) (页面每次出现在屏幕上都触发，包括从下级页面点返回露出当前页面)
  onShow: function onShow() {},
  // 监听 - 页面每次【隐藏时】执行(如：返回)
  onHide: function onHide() {},
  // 函数
  methods: {
    logout: function logout() {
      vk.userCenter.logout({
        success: function success(data) {
          // 退出成功后清楚$store的用户信息
          vk.setVuex('$user.userInfo', {});
          vk.alert("注销成功");
        } });

    },
    // 页面数据初始化函数
    init: function init(options) {
      console.log("init: ", options);
    },
    pageTo: function pageTo(path) {
      vk.navigateTo(path);
    },
    openAddGroutingDialog: function openAddGroutingDialog() {
      vk.navigateTo('/pages/setting/addGroutingDialog/addGroutingDialog');
    },
    openAddEntryofmaterialDialog: function openAddEntryofmaterialDialog() {
      vk.navigateTo('/pages/setting/addEntryofmaterialDialog/addEntryofmaterialDialog');
    },
    openAddDescentofmaterialDialog: function openAddDescentofmaterialDialog() {
      vk.navigateTo('/pages/setting/addDescentofmaterialDialog/addDescentofmaterialDialog');
    },
    openManageGroutingDialog: function openManageGroutingDialog() {
      vk.navigateTo('/pages/setting/manageGrouting/manageGrouting');
    },
    openManageEntrymaterialDialog: function openManageEntrymaterialDialog() {
      vk.navigateTo('/pages/setting/manageEntrymaterial/manageEntrymaterial');
    },
    openManageDescentmaterialDialog: function openManageDescentmaterialDialog() {
      vk.navigateTo('/pages/setting/manageDescentmaterial/manageDescentmaterial');
    },
    addRealName: function addRealName() {
      this.flag = true; //回复按钮可用状态
      // 真实姓名添加过程中不能为空值
      if (this.realName == '') {
        that.$refs["toast"].open({
          message: '姓名不能为空值！',
          position: 'middle ',
          type: 'error',
          iconSize: 50 });

        this.flag = false; //回复按钮可用状态
        return;

      }


      uni.getUserProfile({
        desc: "用于快速设置昵称头像",
        success: function success(res) {var
          userInfo = res.userInfo;
          console.log("这里有值吗？-----这里要更新用户信息", that.realName);
          vk.userCenter.updateUser({
            data: {
              nickname: userInfo.nickName,
              avatar: userInfo.avatarUrl,
              gender: userInfo.gender },

            success: function success(data) {

              that.$refs["toast"].open({
                message: data.msg,
                position: 'middle ',
                type: 'success ',
                iconSize: 50 });


            } });

        } });



      // 回调形式 success fail complete
      vk.callFunction({
        url: 'client/user/kh/common/addRealName',
        title: '添加中...',
        data: {
          realName: that.realName },

        success: function success(data) {
          console.log("这里能够捕捉到这个错误码？", data);
          if (data.code == 0) {

            vk.setVuex('$user.userInfo.realName', that.realName);

          } else {

            that.$refs["toast"].open({
              message: data.msg,
              position: 'middle ',
              type: 'error',
              iconSize: 50 });

          }

        } });



    },
    goToImage: function goToImage(imagePath) {
      uni.previewImage({
        urls: [imagePath],
        longPressActions: {
          itemList: ['发送给朋友', '保存图片', '收藏'],
          success: function success(data) {

          },
          fail: function fail(err) {
            console.log(err.errMsg);
          } } });


    } },


